<?php
require_once ROOT.'/src/place-review.php';
try{$actor=crActor();}catch(DomainException $e){http_response_code(403);exit(e(socialT('login_required')));}
$title=crT('review');$error='';$notice='';$tab=in_array($_GET['filter']??'', ['places','reports','photos','corrections'],true)?$_GET['filter']:(crAdmin()?'places':'reports');
if($_SERVER['REQUEST_METHOD']==='POST')try{
 $kind=$_POST['kind']??'';$id=socialString($_POST['id']??'',95);$action=$_POST['decision']??'';$reason=socialString($_POST['note']??'',1000,0);
 if($kind==='place_submission')prDecide($id,$action,(string)($_POST['version']??''),$reason);
 elseif($kind==='permissions'){if(!crAdmin())throw new DomainException('not_found');$member=socialQuery("SELECT id FROM members WHERE handle=? AND state='active'",[$id])->fetchColumn();if(!$member)throw new DomainException('not_found');$before=socialQuery('SELECT * FROM community_permissions WHERE member=?',[$member])->fetch();$after=[!empty($_POST['reviewer'])?1:0,!empty($_POST['photos'])?1:0];socialQuery('INSERT INTO community_permissions VALUES(?,?,?) ON CONFLICT(member) DO UPDATE SET reviewer=excluded.reviewer,photos=excluded.photos',[$member,...$after]);crAudit($actor,$kind,$member,'permissions',$before,$after,$reason);}
 elseif($kind==='limits'){if(!crAdmin())throw new DomainException('not_found');foreach(['post','correction','photo','comment'] as $k){$n=filter_var($_POST[$k]??'',FILTER_VALIDATE_INT);if($n===false||$n<1||$n>1000)throw new DomainException('invalid');}foreach(['post','correction','photo','comment'] as $k)socialQuery('INSERT INTO network_settings VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value',['launch_limit_'.$k,(int)$_POST[$k]]);crAudit($actor,'settings','launch','limits',[],array_intersect_key($_POST,array_flip(['post','correction','photo','comment'])),$reason);}
 elseif($kind==='correction')crCorrectionDecision($id,$action,$reason);
 elseif($kind==='photo')crPhotoDecision($id,$action,$reason);
 elseif($kind==='report'){$report=socialQuery('SELECT * FROM community_reports WHERE id=?',[$id])->fetch();if(!$report)throw new DomainException('not_found');if($action!=='resolve'){if($report['kind']==='photo')crPhotoDecision($report['target'],$action,$reason);elseif($report['kind']==='correction')crCorrectionDecision($report['target'],$action==='restore'?'unhide':$action,$reason);else crContentDecision($report['kind'],$report['target'],$action,$reason);}socialQuery("UPDATE community_reports SET state='resolved' WHERE id=?",[$id]);crAudit($actor,'report',$id,$action,'pending','resolved',$reason);}
 elseif($kind==='new_place'){if(!crAdmin())throw new DomainException('not_found');$row=socialQuery("SELECT * FROM member_places WHERE id=? AND state='pending'",[$id])->fetch();if(!$row||$row['owner']===(socialUser()['id']??''))throw new DomainException('conflict');if(!in_array($action,['approve','reject','needs_info'],true))throw new DomainException('invalid');socialDb()->beginTransaction();try{$state=['approve'=>'approved','reject'=>'rejected','needs_info'=>'needs_info'][$action];socialQuery('UPDATE member_places SET state=?,moderator_note=? WHERE id=?',[$state,$reason,$id]);if($action==='approve'){$doc=json_decode($row['document'],true);networkApproveLocale('place',$id,$doc['language'],$doc,$actor);}crAudit($actor,'new_place',$id,$action,'pending',$state,$reason);socialDb()->commit();}catch(Throwable $e){socialDb()->rollBack();throw $e;}}
 else crContentDecision($kind,$id,$action,$reason);
 $notice=uiMessage('admin.release.37');
}catch(DomainException $e){$error=socialT($e->getMessage());}
function crReviewButtons(string $kind,string $id,array $actions): void {if(!$actions)return;echo '<form method="post">'.csrf().'<input type="hidden" name="kind" value="'.e($kind).'"><input type="hidden" name="id" value="'.e($id).'"><label>'.e(prT('note')).'<textarea name="note" maxlength="1000"></textarea></label>';foreach($actions as $key=>$label)echo '<button '.($key==='approve'?'formnovalidate ':'').'name="decision" value="'.e($key).'">'.e($label).'</button>';echo '</form>';}
ob_start();?><div class="social-page"><h1><?=e($title)?></h1><p><?=e(uiMessage('admin.release.38'))?></p><nav class="pr-tabs"><?php if(crAdmin()):?><a href="?filter=places"><?=e(prT('tab'))?></a><?php endif?><a href="?filter=reports"><?=e(uiMessage('admin.release.39'))?></a><a href="?filter=photos"><?=e(uiMessage('admin.release.40'))?></a><a href="?filter=corrections"><?=e(uiMessage('admin.release.41'))?></a><?php if(crAdmin()):?><a href="/KNISA/community/?view=history"><?=e(uiMessage('admin.release.42'))?></a><?php endif?></nav><?php if($error):?><p role="alert"><?=e($error)?></p><?php endif?><?php if($notice):?><p role="status"><?=e($notice)?></p><?php endif?>
<?php $reviewState=in_array($_GET['status']??'',['approved','rejected','needs_info','hidden'],true)?$_GET['status']:'pending';if(in_array($tab,['photos','corrections'],true)){echo '<nav class="pr-tabs">';foreach(['pending','approved','rejected','needs_info','hidden'] as $state)echo '<a href="?filter='.e($tab).'&amp;status='.e($state).'">'.e(crT($state)).'</a>';echo '</nav>';}if($tab==='places'):prRender();elseif($tab==='photos'):foreach(socialQuery("SELECT p.*,m.handle FROM community_photo_review p JOIN members m ON m.id=p.owner WHERE p.state=? ORDER BY p.created DESC LIMIT 100",[$reviewState]) as $r):if(!crPhotoSubmitted($r['id']))continue;?><article class="social-card"><p>@<?=e($r['handle'])?> · <?=e(crT($r['state']))?> · <?=e(gmdate('Y-m-d',$r['created']))?></p><img src="/community/media/<?=e($r['id'])?>/" alt="תמונה לבדיקה" style="max-width:100%;max-height:360px"><?php crReviewButtons('photo',$r['id'],$r['state']==='hidden'?['restore'=>uiMessage('admin.release.43')]:($r['state']==='approved'?['hide'=>'הסתרה']:(in_array($r['state'],['pending','needs_info'],true)?['approve'=>uiMessage('admin.release.44'),'reject'=>'דחייה','needs_info'=>uiMessage('admin.release.45')]:[])));?></article><?php endforeach;
elseif($tab==='corrections'):foreach(socialQuery("SELECT c.*,m.handle FROM community_corrections c JOIN members m ON m.id=c.owner WHERE c.state=? ORDER BY c.created DESC LIMIT 100",[$reviewState]) as $r):?><article class="social-card"><h2><?=e($r['field']==='location'?crT('location'):cpT($r['field']))?> · <?=e($r['language'])?></h2><p>@<?=e($r['handle'])?> · <?=e(crT($r['state']))?></p><p><?=e((scCatalogue()[$r['place']]['title']??$r['place']))?></p><dl><dt><?=e(uiMessage('admin.release.46'))?></dt><dd><?=e(is_array(json_decode($r['previous'],true))?implode(', ',array_filter(json_decode($r['previous'],true),fn($x)=>$x!==null)):(json_decode($r['previous'],true)?:'—'))?></dd><dt><?=e(uiMessage('admin.release.47'))?></dt><dd><?=e(is_array(json_decode($r['value'],true))?implode(', ',json_decode($r['value'],true)):json_decode($r['value'],true))?></dd><dt><?=e(uiMessage('admin.release.48'))?></dt><dd><?=e($r['explanation'])?></dd></dl><?php if(!in_array($r['field'],['location','address','description'],true)||crAdmin())crReviewButtons('correction',$r['id'],$r['state']==='hidden'?['unhide'=>uiMessage('admin.release.49')]:($r['state']==='approved'?['restore'=>uiMessage('admin.release.50')]:(in_array($r['state'],['pending','needs_info'],true)?['approve'=>uiMessage('admin.release.44'),'reject'=>'דחייה','needs_info'=>uiMessage('admin.release.45')]:[])));else echo '<p>שינוי מיקום, כתובת או תיאור שעשוי להשפיע על גישה ובטיחות דורש מנהל</p>';?></article><?php endforeach;if(crAdmin()&&$reviewState==='pending'):foreach(socialQuery("SELECT p.*,m.handle FROM member_places p JOIN members m ON m.id=p.owner WHERE p.state='pending' ORDER BY p.created LIMIT 100") as $r):$doc=json_decode($r['document'],true);?><article class="social-card"><h2>מקום חדש: <?=e($doc['title'])?></h2><p>@<?=e($r['handle'])?></p><p><?=e(($doc['city']??'').' · '.($doc['address']??''))?></p><p><?=e($doc['description']??'')?></p><?php crReviewButtons('new_place',$r['id'],['approve'=>uiMessage('admin.release.44'),'reject'=>'דחייה','needs_info'=>uiMessage('admin.release.45')]);?></article><?php endforeach;endif;
else:foreach(socialQuery("SELECT r.*,m.handle FROM community_reports r JOIN members m ON m.id=r.owner ORDER BY (r.state='pending') DESC,(r.reason='privacy') DESC,(r.reason='inappropriate') DESC,r.created LIMIT 100") as $r):?><article class="social-card"><h2><?=e(crT($r['reason']))?></h2><p>@<?=e($r['handle'])?> · <?=e($r['kind'].' · '.$r['target'].' · '.$r['state'])?></p><p><?=e($r['body'])?></p><?php if(in_array($r['kind'],['post','trip','place'],true)):?><a href="<?=e(networkUrl($r['kind'],$r['target']))?>" target="_blank" rel="noopener"><?=e(uiMessage('admin.release.52'))?></a><?php endif;crReviewButtons('report',(string)$r['id'],['hide'=>uiMessage('admin.release.53'),'restore'=>uiMessage('admin.release.43'),'resolve'=>'סגירת דיווח']);?></article><?php endforeach;endif;?>
<?php if(crAdmin()):?><details class="social-card"><summary><?=e(uiMessage('admin.release.54'))?></summary><p><?=e(uiMessage('admin.release.55'))?></p><form method="post"><?=csrf()?><input type="hidden" name="kind" value="permissions"><label>שם משתמש<input name="id" required></label><label><input type="checkbox" name="reviewer"> <?=e(uiMessage('admin.release.56'))?></label><label><input type="checkbox" name="photos"> <?=e(uiMessage('admin.release.57'))?></label><label><?=e(uiMessage('admin.release.58'))?><input name="note" required minlength="3"></label><button>שמירה</button></form><?php foreach(socialQuery('SELECT p.*,m.handle FROM community_permissions p JOIN members m ON m.id=p.member') as $r):?><p><?=e($r['handle'])?> · בודק: <?=(int)$r['reviewer']?> · תמונות: <?=(int)$r['photos']?></p><?php endforeach?></details><details class="social-card"><summary><?=e(uiMessage('admin.release.59'))?></summary><form method="post"><?=csrf()?><input type="hidden" name="kind" value="limits"><?php foreach(['post'=>30,'correction'=>5,'photo'=>150,'comment'=>10] as $k=>$n):?><label><?=e($k)?><input type="number" name="<?=$k?>" min="1" max="1000" value="<?=(int)(socialQuery('SELECT value FROM network_settings WHERE key=?',['launch_limit_'.$k])->fetchColumn()?:$n)?>" required></label><?php endforeach?><label><?=e(uiMessage('admin.release.58'))?><input name="note" required minlength="3"></label><button>שמירה</button></form></details><?php endif?></div><?php $content=ob_get_clean();require ROOT.'/views/layout.php';


